import { NgClass, NgFor, NgIf } from '@angular/common';
import { AfterViewInit, ChangeDetectorRef, Component, ElementRef, EventEmitter, Input, OnInit, Optional, Output, Self, ViewChild, ViewEncapsulation } from '@angular/core';
import { FormControl, FormGroupDirective, FormsModule, NgControl, NgForm, ReactiveFormsModule } from '@angular/forms';
import { MatInput, MatInputModule } from '@angular/material/input';
import { MAT_FORM_FIELD_DEFAULT_OPTIONS, MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatButtonModule } from '@angular/material/button';
import { coerceBooleanProperty } from '@angular/cdk/coercion';
import { A11yModule } from '@angular/cdk/a11y';

import { NgxMaskDirective, provideNgxMask } from 'ngx-mask';

import { BaseComponent } from 'sidsc-components/core';
import { DscTooltipModule } from 'sidsc-components/dsc-tooltip';
import { MatAutocompleteModule } from '@angular/material/autocomplete';

import { debounceTime } from 'rxjs/operators';


@Component({
  selector: 'dsc-input',
  standalone: true,
  templateUrl: './dsc-input.component.html',
  styleUrls: ['./dsc-input.component.scss'],
  encapsulation: ViewEncapsulation.None,
  imports: [
    NgIf,
    NgFor,
    NgClass,
    FormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatIconModule,
    MatTooltipModule,
    DscTooltipModule,
    MatButtonModule,
    NgxMaskDirective,
    ReactiveFormsModule,
    A11yModule,
    MatAutocompleteModule
  ],
  providers: [
    provideNgxMask(),
    { provide: MAT_FORM_FIELD_DEFAULT_OPTIONS, useValue: { appearance: 'outline' } }
  ]
})
export class DscInputComponent extends BaseComponent<any> implements OnInit, AfterViewInit {
  @ViewChild(MatInput, { static: true }) matInput!: MatInput;
  @Output() keydown: EventEmitter<any> = new EventEmitter<any>();

  @Output() search = new EventEmitter<string>()

  @Input() suffix: string = '';

  @Input() mask?: string;

  @Input() dropSpecialCharacters: boolean = false;

  @Input() iconPrefix?: string;

  @Input() iconSuffix?: string;

  @Input() iconStyle: 'outlined' | 'filled' | 'rounded' | 'sharp' | 'two-tone' = 'filled';

  @Input() options : string[] = [];

  @Input() autocompleteControl = new FormControl(''); 

  @Input()
  get showCharCounter(): boolean {
    return this._showCharCounter;
  }

  set showCharCounter(value: boolean | string) {
    this._showCharCounter = coerceBooleanProperty(value);
  }

  isActive: boolean = false;

  tooltipId = `tt-${cryptoRandom()}`;

  private _showCharCounter = false;

  @Input()
  get showClearButton(): boolean {
    return this._showClearButton;
  }

  set showClearButton(value: boolean | string) {
    this._showClearButton = coerceBooleanProperty(value);
  }

  private _showClearButton = false;

  hidePassword = true;

  filteredOptions: string[] = [];

  @ViewChild('input', { static: false }) inputEl!: ElementRef<HTMLInputElement>;

  constructor(@Optional() @Self() public ngControl: NgControl,
              @Optional() parentForm: NgForm,
              @Optional() parentFormGroup: FormGroupDirective,
              private cdr: ChangeDetectorRef
  ) {
    super(ngControl, parentForm, parentFormGroup);
    if (this.ngControl) this.ngControl.valueAccessor = this;
  }

  ngOnInit(): void {
    
    const initial = this.ngControl?.control?.value ?? this.ngControl?.value ?? '';
    this.val = initial ?? '';
    this.filteredOptions = this._filter(this.val);

    if (this.ngControl?.valueChanges) {
      this.ngControl.valueChanges.pipe(
        debounceTime(300)
      ).subscribe(value => {
        this.specialCharacters(value);
      });
    }
  }

  specialCharacters(value: any) {
    let query = '';
    if(this.dropSpecialCharacters) {
      query = this.inputEl.nativeElement.value || '';
      this.val = this.inputEl.nativeElement.value;

    } else {
      const query = value || '';
    }

    this.search.emit(query); 
    this.filteredOptions = this._filter(query);
  }

  private _filter(value: string | number | null | undefined): string[] {
    const filterValue = (value ?? '').toString().toLowerCase();
    return this.options.filter(option => option.toLowerCase().includes(filterValue));
  }
  
  ngAfterViewInit(): void {
    Promise.resolve().then(() => {
      const ctrlVal = this.ngControl?.control?.value ?? this.val ?? '';
      if (this.inputEl?.nativeElement) {
        this.inputEl.nativeElement.value = ctrlVal;
      }
      this.cdr.markForCheck();
    });
  }

  onInput(event: Event): void {
    const input = event.target as HTMLInputElement;
    const value = input?.value ?? '';
    this.val = value;
    this.filteredOptions = this._filter(value);
    this.onChange(value);
    this.onTouched();
  }

  onOptionSelected(event: any): void {
    this.val = event.option.value;
    this.onChange(this.val);
    this.onTouched();
  }


  get formFieldClasses(): string[] {
    return [
      this.ngControl && this.ngControl.value?.length
        ? 'mat-mdc-form-field--filled'
        : 'mat-mdc-form-field--empty',
      this.readOnly ? 'mat-mdc-form-field--readonly' : '',
      this.ngControl &&
      this.ngControl.invalid &&
      (this.ngControl.touched || this.ngControl.dirty) &&
      !this.readOnly
        ? 'error-field'
        : '',
      (this.isActive && !this.errorText) || (this.ngControl && this.ngControl.value)
        ? 'active-field'
        : ''
    ].filter(Boolean);
  }

  getIconClass(): string {
    if (this.iconStyle === 'filled') return 'material-icons';
    if (this.iconStyle === 'rounded') return 'material-icons-round';
    return `material-icons-${this.iconStyle}`;
  }

  onKeydown($event: KeyboardEvent): void {
    if ($event.code === 'Space') $event.stopPropagation();
  }

  
  override writeValue(value: any): void {
    this.val = value || '';
  }

  override registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  override registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

}

function cryptoRandom() {
  return Math.random().toString(36).slice(2);
}
